#include <ambient.h>
#include <sensor_drivers.h>

int main(void) {
    // Initialize system
    ambient_init();
    sensor_config_t sensor;
    model_t model_obj;

    // Load AI model
    ambient_load_model(&model_obj, "fall_detect.bin");

    while(1) {
        ambient_read_i2s_mic(&sensor);

        ambient_run_fft(&sensor);

        run_ai_inference(&model_obj);

        if(model_obj.result > THRESHOLD) {
            trigger_alert();
        }
    }
}
